// Daily plan: renewal reminders (staged), claim document chasers, agent digest
const cfg = $('Config').first().json;
const tz = 'Asia/Kolkata';
const today = cfg.demo_today ? DateTime.fromISO(cfg.demo_today, { zone: tz }).startOf('day') : DateTime.now().setZone(tz).startOf('day');
const nowIso = DateTime.now().setZone(tz).toISO();
const stages = String(cfg.reminder_days).split(',').map(s => Number(s.trim())).filter(s => !isNaN(s));
const clean = (s, max = 200) => String(s ?? '').replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, max);
const money = v => cfg.currency_symbol + Number(String(v).replace(/[^0-9.]/g, '') || 0).toLocaleString('en-IN');
const waNum = p => { let d = String(p || '').replace(/\D/g, '').replace(/^0+/, ''); if (d.length === 10) d = '91' + d; return d; };
const inactive = ['renewed', 'lapsed', 'cancelled', 'surrendered'];

const policies = $('Read Policies').all().map(i => i.json).filter(p => p.policy_id);
const claims = $('Read Claims').all().map(i => i.json).filter(c => c.claim_id);
const out = [];
const digest = { due7: [], grace: [], docsPending: [], ready: [] };

// ---------- Renewals ----------
for (const p of policies) {
  if (inactive.includes(String(p.status || '').toLowerCase())) continue;
  const due = DateTime.fromISO(String(p.renewal_date), { zone: tz });
  if (!due.isValid) continue;
  const days = Math.round(due.diff(today, 'days').days);
  if (days <= 7 && days >= 0) digest.due7.push(`${p.customer_name} (${p.policy_type}, ${days === 0 ? 'today' : days + 'd'})`);
  if (days < 0 && days >= -Number(cfg.grace_days)) digest.grace.push(`${p.customer_name} (${p.policy_type}, ${-days}d overdue)`);
  if (days < -Number(cfg.grace_days)) continue;
  const eligible = stages.filter(s => s >= days);
  if (!eligible.length) continue;
  const stage = Math.min(...eligible);
  if (String(p.last_reminder_stage) !== '' && Number(p.last_reminder_stage) === stage) continue;
  const dueText = days > 1 ? `in ${days} days` : days === 1 ? 'tomorrow' : days === 0 ? 'TODAY' : `- it was due ${-days} day(s) ago, grace period ends soon`;
  out.push({ json: {
    kind: 'renewal', policy_id: p.policy_id, stage, sent_at: nowIso, phone_wa: waNum(p.phone), customer_name: p.customer_name,
    wati_payload: { template_name: cfg.wati_template_renewal, broadcast_name: `renewal_${p.policy_id}_${stage}`, parameters: [
      { name: 'name', value: clean(String(p.customer_name).split(' ')[0], 40) },
      { name: 'policy_type', value: clean(p.policy_type, 40) },
      { name: 'policy_no', value: clean(p.policy_no, 40) },
      { name: 'insurer', value: clean(p.insurer, 60) },
      { name: 'due_text', value: dueText },
      { name: 'due_date', value: due.toFormat('dd LLL yyyy') },
      { name: 'premium', value: money(p.premium) },
      { name: 'agent_name', value: clean(cfg.agent_name, 60) }
    ]}
  }});
}

// ---------- Claims document chasers ----------
const split = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
for (const c of claims) {
  const st = String(c.status || '').toLowerCase();
  const pending = split(c.required_docs).filter(d => !split(c.docs_received).map(x => x.toLowerCase()).includes(d.toLowerCase()));
  if (st.startsWith('docs complete')) digest.ready.push(`${c.claim_id} ${c.customer_name}`);
  if (!st.startsWith('docs pending') || !pending.length) continue;
  digest.docsPending.push(`${c.claim_id} ${c.customer_name} (${pending.length} docs)`);
  const last = DateTime.fromISO(String(c.last_chase_at || c.created_at || ''), { zone: tz });
  if (last.isValid && today.diff(last.startOf('day'), 'days').days < Number(cfg.chase_every_days)) continue;
  out.push({ json: {
    kind: 'chase', claim_id: c.claim_id, sent_at: nowIso, phone_wa: waNum(c.phone), customer_name: c.customer_name,
    wati_payload: { template_name: cfg.wati_template_docs, broadcast_name: `docs_${c.claim_id}_${today.toISODate()}`, parameters: [
      { name: 'name', value: clean(String(c.customer_name).split(' ')[0], 40) },
      { name: 'claim_type', value: clean(`${c.policy_type} ${c.claim_type || ''}`, 60) },
      { name: 'claim_id', value: clean(c.claim_id, 40) },
      { name: 'pending_docs', value: clean(pending.join(', '), 400) },
      { name: 'agent_name', value: clean(cfg.agent_name, 60) }
    ]}
  }});
}

// ---------- Agent digest ----------
const sect = (t, arr) => `${t}: ${arr.length ? arr.slice(0, 6).join('; ') + (arr.length > 6 ? ` +${arr.length - 6} more` : '') : 'none'}`;
const renewalsSent = out.filter(o => o.json.kind === 'renewal').length;
const chasesSent = out.filter(o => o.json.kind === 'chase').length;
const summary = clean([
  `${today.toFormat('dd LLL')}: ${renewalsSent} renewal reminders + ${chasesSent} doc reminders sent`,
  sect('Due in 7 days', digest.due7), sect('In grace period', digest.grace),
  sect('Claims waiting for docs', digest.docsPending), sect('Ready to submit to insurer', digest.ready)
].join(' | '), 1000);
out.push({ json: { kind: 'digest', phone_wa: waNum(cfg.agent_whatsapp), wati_payload: {
  template_name: cfg.wati_template_digest, broadcast_name: `digest_${today.toISODate()}`,
  parameters: [{ name: 'agent_name', value: clean(cfg.agent_name, 60) }, { name: 'summary', value: summary }] } } });
return out;

// Keep only real customer messages from the WATI webhook
const cfg = $('Config').first().json;
const b = $input.first().json.body || {};
const agent = String(cfg.agent_whatsapp).replace(/\D/g, '');
if (b.eventType && b.eventType !== 'message') return [];
if (b.owner === true || !b.waId || String(b.waId) === agent) return [];
const type = String(b.type || 'text').toLowerCase();
const isMedia = ['image', 'document', 'video'].includes(type);
let fileName = '';
if (isMedia && b.data) { const m = String(b.data).match(/fileName=([^&]+)/); fileName = m ? decodeURIComponent(m[1]) : String(b.data); }
return [{ json: {
  wa_id: String(b.waId), sender_name: b.senderName || '', text: String(b.text || '').trim(),
  msg_type: type, is_media: isMedia, media_file: fileName,
  media_caption: b.caption || (isMedia ? b.text || '' : ''), received_at: b.timestamp || new Date().toISOString()
}}];

// Match the sender to policies + open claims (by last 10 digits of phone)
const msg = $('Normalize Inbound').first().json;
const last10 = p => String(p || '').replace(/\D/g, '').slice(-10);
const me = last10(msg.wa_id);
const split = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const policies = $('Read Policies (Inbound)').all().map(i => i.json).filter(p => p.policy_id && last10(p.phone) === me);
const closed = ['settled', 'rejected', 'closed', 'withdrawn'];
const claims = $('Read Claims (Inbound)').all().map(i => i.json)
  .filter(c => c.claim_id && last10(c.phone) === me && !closed.includes(String(c.status || '').toLowerCase()))
  .map(c => ({ ...c, pending_docs: split(c.required_docs).filter(d => !split(c.docs_received).map(x => x.toLowerCase()).includes(d.toLowerCase())) }));
return [{ json: {
  ...msg,
  customer_name: policies[0]?.customer_name || msg.sender_name || 'Customer',
  known_customer: policies.length > 0,
  policies: policies.map(p => ({ policy_id: p.policy_id, policy_type: p.policy_type, insurer: p.insurer, policy_no: p.policy_no, renewal_date: p.renewal_date, status: p.status, premium: p.premium })),
  open_claims: claims.map(c => ({ claim_id: c.claim_id, policy_id: c.policy_id, policy_type: c.policy_type, claim_type: c.claim_type, status: c.status, insurer_claim_no: c.insurer_claim_no, docs_received: c.docs_received, doc_links: c.doc_links, required_docs: c.required_docs, pending_docs: c.pending_docs, created_at: c.created_at }))
}}];

