// Turn AI understanding into concrete actions
const cfg = $('Config').first().json;
const m = $('Match Customer').item.json;
let ai = $json.message?.content ?? $json.content ?? {};
if (typeof ai === 'string') { try { ai = JSON.parse(ai.replace(/```json|```/g, '').trim()); } catch (e) { ai = {}; } }
const now = DateTime.now().setZone('Asia/Kolkata');
let reqDocs = {};
try { reqDocs = JSON.parse(cfg.required_docs_by_type); } catch (e) {}
const docsFor = type => {
  const k = Object.keys(reqDocs).find(k => String(type || '').toLowerCase().includes(k.toLowerCase()));
  return reqDocs[k || 'Default'] || reqDocs.Default || [];
};
const intent = String(ai.intent || 'OTHER').toUpperCase();
let reply = String(ai.reply || '').trim();
let needsAgent = !!ai.needs_agent || !m.known_customer;
let agentNote = ai.agent_note || '';
let claim = null, claimChanged = false, policyUpdate = null;

const findPolicy = id => m.policies.find(p => p.policy_id === id) || (m.policies.length === 1 ? m.policies[0] : null);
const findClaim = id => m.open_claims.find(c => c.claim_id === id) || (m.open_claims.length === 1 ? m.open_claims[0] : null);

if (intent === 'CLAIM_NEW') {
  const pol = findPolicy(ai.policy_id);
  const existing = pol && m.open_claims.find(c => c.policy_id === pol.policy_id);
  if (existing) {
    claim = { ...existing };
    reply += ` Your claim ${existing.claim_id} is already open (status: ${existing.status}).` + (existing.pending_docs.length ? ` Still needed: ${existing.pending_docs.join(', ')}.` : '');
  } else if (pol) {
    const required = docsFor(pol.policy_type);
    claim = {
      claim_id: `CLM-${now.toFormat('yyMMdd')}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`,
      policy_id: pol.policy_id, customer_name: m.customer_name, phone: m.wa_id, policy_type: pol.policy_type,
      claim_type: ai.new_claim?.claim_type || '', incident_date: ai.new_claim?.incident_date || '',
      description: ai.new_claim?.description || m.text, status: 'Docs Pending', required_docs: required.join(', '),
      docs_received: '', doc_links: '', created_at: now.toISO(), insurer_claim_no: '', last_chase_at: ''
    };
    claim.pending_docs = required;
    claimChanged = true; needsAgent = true;
    agentNote = `New ${pol.policy_type} claim ${claim.claim_id} (${pol.insurer}). ${claim.description}`.slice(0, 300);
    reply += ` I've registered your claim request (Ref: ${claim.claim_id}). Please send clear photos/PDFs of: ${required.map((d, i) => `${i + 1}) ${d}`).join(' ')}`;
  } else {
    needsAgent = true; agentNote = agentNote || `Claim request but policy unclear: ${m.text}`.slice(0, 300);
  }
}
if (intent === 'DOCUMENT' || m.is_media) {
  const c = findClaim(ai.claim_id);
  if (c) claim = { ...c };
  else { needsAgent = true; agentNote = agentNote || `Document received but no single open claim matched (${m.media_file || 'text'})`; }
}
if (intent === 'CLAIM_STATUS') {
  const c = findClaim(ai.claim_id);
  if (c) reply += ` Claim ${c.claim_id}: *${c.status}*${c.insurer_claim_no ? ` (insurer ref ${c.insurer_claim_no})` : ''}.` + (c.pending_docs.length ? ` Pending documents: ${c.pending_docs.join(', ')}.` : '');
  else if (!m.open_claims.length) reply += ' I could not find an open claim on your number.';
}
if (intent === 'RENEWAL_CONFIRM') {
  const pol = findPolicy(ai.policy_id);
  if (pol) { policyUpdate = { policy_id: pol.policy_id, status: 'Renewal Requested', agent_notes: `Customer confirmed renewal on WhatsApp ${now.toFormat('dd LLL yyyy HH:mm')}` }; }
  needsAgent = true; agentNote = agentNote || `${m.customer_name} wants to renew ${pol ? pol.policy_type + ' ' + pol.policy_no : '(policy unclear)'} — send payment link.`;
}
if (['CALLBACK', 'RENEWAL_HELP', 'COMPLAINT'].includes(intent)) needsAgent = true;

return { json: {
  ...m, ai_intent: intent, ai_language: ai.language || '', document_type: ai.document_type || '',
  reply_base: reply || 'Thank you for your message. Our team will get back to you shortly.',
  claim, claim_changed: claimChanged, policy_update: policyUpdate,
  needs_agent: needsAgent, agent_note: agentNote || m.text.slice(0, 200)
}};

// Merge uploaded document into claim, finalise reply + sheet rows
const cfg = $('Config').first().json;
const d = $('Decide Actions').item.json;
const now = DateTime.now().setZone('Asia/Kolkata').toISO();
const split = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
let reply = d.reply_base, claim = d.claim ? { ...d.claim } : null;
let claimChanged = d.claim_changed, needsAgent = d.needs_agent, agentNote = d.agent_note;

let driveId = null;
try { driveId = $('Upload Doc to Drive').item.json.id; } catch (e) { driveId = null; }

if (d.is_media && claim) {
  if (driveId) {
    const required = split(claim.required_docs);
    const match = required.find(r => r.toLowerCase() === String(d.document_type).toLowerCase());
    const label = match || d.document_type || 'Other document';
    const received = split(claim.docs_received);
    if (!received.map(x => x.toLowerCase()).includes(label.toLowerCase())) received.push(label);
    claim.docs_received = received.join(', ');
    claim.doc_links = [...split(claim.doc_links), `${label}: https://drive.google.com/file/d/${driveId}/view`].join(', ');
    const pending = required.filter(r => !received.map(x => x.toLowerCase()).includes(r.toLowerCase()));
    claim.pending_docs = pending;
    if (!pending.length) {
      claim.status = 'Docs Complete - Ready to Submit';
      needsAgent = true; agentNote = `All documents received for ${claim.claim_id} (${claim.customer_name}). Ready to file with insurer.`;
      reply = `${reply} ✅ Received your ${label}. All documents for claim ${claim.claim_id} are now complete — we will file it with the insurer and update you.`.trim();
    } else {
      reply = `${reply} ✅ Received: ${label}. Still needed for claim ${claim.claim_id}: ${pending.join(', ')}.`.trim();
    }
    claimChanged = true;
  } else {
    reply = `${reply} We had trouble saving that file — could you please send it again?`.trim();
  }
}

const row = claim ? {
  claim_id: claim.claim_id, policy_id: claim.policy_id, customer_name: claim.customer_name, phone: claim.phone || d.wa_id,
  policy_type: claim.policy_type, claim_type: claim.claim_type || '', incident_date: claim.incident_date || '',
  description: claim.description || '', status: claim.status, required_docs: claim.required_docs,
  docs_received: claim.docs_received || '', doc_links: claim.doc_links || '', created_at: claim.created_at || now,
  updated_at: now, insurer_claim_no: claim.insurer_claim_no || ''
} : null;

return { json: {
  wa_id: d.wa_id, customer_name: d.customer_name, intent: d.ai_intent,
  reply_text: reply.slice(0, 4000), claim_changed: claimChanged && !!row, claim_row: row,
  policy_changed: !!d.policy_update, policy_update: d.policy_update,
  needs_agent: needsAgent, agent_whatsapp: String(cfg.agent_whatsapp).replace(/\D/g, ''),
  agent_alert_payload: { template_name: cfg.wati_template_agent_alert, broadcast_name: `alert_${Date.now()}`, parameters: [
    { name: 'customer', value: `${d.customer_name} (+${d.wa_id})`.slice(0, 80) },
    { name: 'intent', value: d.ai_intent },
    { name: 'note', value: String(agentNote || '').replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').slice(0, 500) }
  ]}
}};
